import pandas as pd
import csv
from difflib import ndiff

def task_func(file_path1, file_path2, delimiter=',', quotechar='"'):
    try:
        with open(file_path1, 'r', newline='', encoding='utf-8') as f1:
            lines1 = f1.readlines()

        with open(file_path2, 'r', newline='', encoding='utf-8') as f2:
            lines2 = f2.readlines()

    except FileNotFoundError:
        raise

    except Exception as e:
        raise Exception(str(e)) from e

    if not lines1 or not lines2:
        raise ValueError("Both files must contain at least one line.")

    result = []

    line_num1 = 0
    line_num2 = 0

    for diff_line in ndiff(lines1, lines2):
        status = diff_line[0]
        content = diff_line[1:].rstrip('\n')

        if status == ' ':
            line_num1 += 1
            line_num2 += 1
            line_number = line_num1
        elif status == '-':
            line_num1 += 1
            line_number = line_num1
        elif status == '+':
            line_num2 += 1
            line_number = line_num2
        else:
            continue

        result.append({
            'Line Number': line_number,
            'Status': status,
            'Content': content
        })

    return pd.DataFrame(result, columns=['Line Number', 'Status', 'Content'])

