import warnings
import os
import glob
import shutil
import time


def task_func(SOURCE_DIR, DEST_DIR, EXTENSIONS):
    transferred_files = []

    if not os.path.isdir(SOURCE_DIR):
        warnings.warn(f"Source directory does not exist: {SOURCE_DIR}")
        return transferred_files

    try:
        os.makedirs(DEST_DIR, exist_ok=True)
    except Exception as exc:
        warnings.warn(f"Could not create destination directory: {DEST_DIR}. {exc}")
        return transferred_files

    normalized_extensions = []
    for ext in EXTENSIONS:
        if not isinstance(ext, str):
            warnings.warn(f"Invalid extension: {ext}")
            continue

        ext = ext.strip()
        if not ext:
            continue

        if not ext.startswith("."):
            ext = "." + ext

        normalized_extensions.append(ext)

    if not normalized_extensions:
        return transferred_files

    seen_files = set()

    for ext in normalized_extensions:
        pattern = os.path.join(SOURCE_DIR, f"*{ext}")

        for file_path in glob.glob(pattern):
            if not os.path.isfile(file_path):
                continue

            file_name = os.path.basename(file_path)

            if file_name in seen_files:
                continue

            seen_files.add(file_name)

            dest_path = os.path.join(DEST_DIR, file_name)

            try:
                shutil.copy2(file_path, dest_path)
                transferred_files.append(file_name)
            except Exception as exc:
                warnings.warn(f"Could not transfer file: {file_name}. {exc}")

    return transferred_files

