import pandas as pd
import random
from datetime import datetime

def task_func(
    task_list,
    n_tasks,
    employees=["John Doe", "Jane Smith", "James Brown", "Mary Johnson", "Robert Davis"],
    seed=None,
):
    if n_tasks < 0:
        raise ValueError("If n_tasks is negative.")

    rng = random.Random(seed)
    columns = ["Task Name", "Assigned To", "Due Date"]

    if n_tasks == 0:
        return pd.DataFrame(columns=columns)

    if not task_list:
        return pd.DataFrame(columns=columns)

    if not employees:
        raise ValueError("If employees is empty.")

    if n_tasks <= len(task_list):
        chosen_tasks = rng.sample(task_list, n_tasks)
    else:
        chosen_tasks = rng.choices(task_list, k=n_tasks)

    due_date = datetime.now().date()
    rows = []

    for task in chosen_tasks:
        assigned_to = rng.choice(employees)
        sanitized_task = task.replace(" ", "_")
        rows.append({
            "Task Name": sanitized_task,
            "Assigned To": assigned_to,
            "Due Date": due_date
        })

    return pd.DataFrame(rows, columns=columns)

