import pandas as pd
from datetime import datetime
import random

def task_func(
    epoch_milliseconds,
    random_seed=0,
    products=["Product1", "Product2", "Product3", "Product4", "Product5"],
):
    if not isinstance(epoch_milliseconds, (int, float)):
        raise ValueError("epoch_milliseconds must be a numeric value")

    if epoch_milliseconds < 0:
        raise ValueError("epoch_milliseconds must be non-negative")

    if not isinstance(products, list) or len(products) != 5:
        raise ValueError("products must contain exactly 5 items")

    if not all(isinstance(product, str) for product in products):
        raise ValueError("all products must be strings")

    if not isinstance(random_seed, int):
        raise ValueError("random_seed must be an integer")

    start_datetime = datetime.fromtimestamp(epoch_milliseconds / 1000)
    current_datetime = datetime.now()

    if start_datetime > current_datetime:
        raise ValueError("epoch_milliseconds must not be in the future")

    random.seed(random_seed)

    start_date = start_datetime.date()
    current_date = current_datetime.date()

    data = []

    for day in pd.date_range(start_date, current_date, freq="D"):
        for product in products:
            sales = random.randint(10, 50)
            data.append(
                {
                    "Product": product,
                    "Date": day.to_pydatetime(),
                    "Sales": sales,
                }
            )

    return pd.DataFrame(data, columns=["Product", "Date", "Sales"])

